import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"执行器模型与路由","description":"Hearth 执行器模型、能力矩阵、路由原则与多个执行器之间的协作方式。","frontmatter":{"title":"执行器模型与路由","description":"Hearth 执行器模型、能力矩阵、路由原则与多个执行器之间的协作方式。","outline":[2,3]},"headers":[],"relativePath":"architecture/executor-model.md","filePath":"architecture/executor-model.md","lastUpdated":null}'),o={name:"architecture/executor-model.md"};function n(l,t,i,s,c,p){return e(),a("div",null,[...t[0]||(t[0]=[r(`<p class="eyebrow">EXECUTOR MODEL</p><h1 id="执行器模型与路由" tabindex="-1">执行器模型与路由 <a class="header-anchor" href="#执行器模型与路由" aria-label="Permalink to &quot;执行器模型与路由&quot;">​</a></h1><p class="lead">执行器不是 Worker 列表，而是拥有明确能力、风险边界和输出契约的并列执行主体。</p><h2 id="executor-不是-worker-列表" tabindex="-1">Executor 不是 Worker 列表 <a class="header-anchor" href="#executor-不是-worker-列表" aria-label="Permalink to &quot;Executor 不是 Worker 列表&quot;">​</a></h2><p>Hearth 使用并列 <code>Executor</code>，而不是把所有东西塞进一个“万能 Agent”：</p><ul><li><strong>Native Runtime</strong>：内置通用推理与短工具循环；</li><li><strong>Codex Executor</strong>：高能力工作区执行器，覆盖代码、研究和文档；</li><li><strong>Connector Executor</strong>：邮件、日历、文档、云盘、IM、Issue Tracker；</li><li><strong>Browser Executor</strong>：网页、表单、登录态和 SaaS；</li><li><strong>GUI Executor</strong>：没有 API 的桌面应用；</li><li><strong>Document/Data Executor</strong>：解析、转换、表格、对账和确定性处理；</li><li><strong>Human Executor</strong>：审批、判断、接管和高风险责任。</li></ul><p>同一任务可由多个执行器协作；执行器之间不共享凭据、文件和隐式上下文。</p><h2 id="能力矩阵" tabindex="-1">能力矩阵 <a class="header-anchor" href="#能力矩阵" aria-label="Permalink to &quot;能力矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>Native</th><th>Codex</th><th>Connector</th><th>Browser</th><th>GUI</th><th>Document/Data</th><th>Human</th></tr></thead><tbody><tr><td>代码、测试、Issue、PR</td><td>中</td><td>强</td><td>弱</td><td>弱</td><td>弱</td><td>弱</td><td>审查</td></tr><tr><td>调研与结构化研究</td><td>强</td><td>强</td><td>中</td><td>强</td><td>弱</td><td>弱</td><td>判断</td></tr><tr><td>文档生成与修改</td><td>中</td><td>强</td><td>中</td><td>中</td><td>中</td><td>强</td><td>验收</td></tr><tr><td>Shell 与文件转换</td><td>中</td><td>强</td><td>弱</td><td>弱</td><td>中</td><td>强</td><td>否</td></tr><tr><td>邮件/日历</td><td>弱</td><td>弱</td><td>强</td><td>中</td><td>中</td><td>弱</td><td>审批</td></tr><tr><td>登录与表单</td><td>弱</td><td>弱</td><td>中</td><td>强</td><td>中</td><td>弱</td><td>接管</td></tr><tr><td>桌面应用</td><td>弱</td><td>弱</td><td>弱</td><td>弱</td><td>强</td><td>弱</td><td>接管</td></tr><tr><td>常驻事件</td><td>强</td><td>弱</td><td>强</td><td>弱</td><td>弱</td><td>弱</td><td>否</td></tr><tr><td>长期记忆</td><td>中</td><td>弱</td><td>弱</td><td>弱</td><td>弱</td><td>弱</td><td>审核</td></tr><tr><td>高风险副作用</td><td>弱</td><td>弱</td><td>强</td><td>强</td><td>强</td><td>弱</td><td>强</td></tr></tbody></table><p>矩阵不是固定结论，必须由真实任务和失败数据更新。Codex 可接收 Connector 取回的邮件、日历和文档片段做理解、研究与草稿；真正发送、邀请、删除或发布仍由 Connector、Credential Broker 和审批链路完成。</p><h2 id="路由原则" tabindex="-1">路由原则 <a class="header-anchor" href="#路由原则" aria-label="Permalink to &quot;路由原则&quot;">​</a></h2><p>不存在“永远先用 Native，最后才用 Codex”的固定顺序。路由是带硬约束的优化：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>候选执行器</span></span>
<span class="line"><span>  → capability 匹配</span></span>
<span class="line"><span>  → 权限与数据驻留检查</span></span>
<span class="line"><span>  → 预期成功率</span></span>
<span class="line"><span>  → Token / 成本 / 延迟</span></span>
<span class="line"><span>  → 风险与可逆性惩罚</span></span>
<span class="line"><span>  → 选择最大化用户价值的方案</span></span></code></pre></div><p>实用判断顺序：</p><ol><li>不需要模型：cron、规则、SQL、脚本、文件 diff、官方 API。</li><li>需要外部数据或副作用：优先 Connector；没有 API 用 Browser；没有浏览器接口用 GUI。</li><li>确定性文档/数据转换：Document/Data。</li><li>长链路、多文件、多产物、复杂研究、代码或深度写作：Codex。</li><li>高频、短、低风险、隐私敏感或低预算推理：Native + 小模型/本地模型。</li><li>价值判断、责任承担或异常接管：Human。</li></ol><p>风险、权限和数据驻留是硬约束，不能用高分抵消。</p><h2 id="执行器协作" tabindex="-1">执行器协作 <a class="header-anchor" href="#执行器协作" aria-label="Permalink to &quot;执行器协作&quot;">​</a></h2><p>典型任务：“查找三份竞品资料，整理成对比表，写进周报，并把关键结论发邮件给团队。”</p><p>可能的链：</p><ol><li>Browser 获取网页；</li><li>Native 提取归纳；</li><li>Document/Data 生成表格；</li><li>Codex 处理长文档、格式和引用；</li><li>Human 审批邮件；</li><li>Connector 发送并产生 Receipt；</li><li>Memory 记录项目背景和承诺；</li><li>Evolution 观察是否值得沉淀技能。</li></ol><p>每一步有独立输入、输出、预算和验证器。</p>`,21)])])}const x=d(o,[["render",n]]);export{u as __pageData,x as default};
